head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > placeholder]<br/>SearchBox 컴포넌트의 입력값이 없을때 표시될 PlaceHolder 텍스트를 설정합니다.",
    "validation" : [
        "ref 속성으로 DataList 컬럼을 바인딩하면, 행을 선택하지 않은 초기 상태에서 PlaceHolder 텍스트가 표시되어야 합니다.",
        "GridView 의 행을 선택하면 해당 행의 컬럼값이 searchbox 에 표시되고 PlaceHolder 가 사라져야 합니다.",
        "GridView 의 행 선택을 해제하면 ref 바인딩 값이 빈값이 되어 PlaceHolder 가 다시 표시되어야 합니다.",
    ]
}



scwin.onpageload = async function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    await scwin.comp_init();

    // 초기 행 미선택 상태 (placeholder 표시)
    dlt_ref.setRowPosition();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 gridview1 있으면 삭제
    if (typeof gridview1 !== 'undefined') {
        gridview1.remove();
    }

    let properties = {
        ref : "data:dlt_ref.name",
        placeholder : "행을 선택하세요",
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicSearchBox(cList);

    // GridView 를 grp_comp 하위에 동적 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strGrid = '';

    strGrid += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_ref" style="width: 400px; height: 150px;" defaultRowHeight="25" rowNumVisible="true" rowNumWidth="30" selectionMode="singlerow" syncRowPositionOption="select">';
    strGrid += '<w2:caption id="caption1" value="DataList 바인딩 GridView (행 선택 시 searchbox 표시)"></w2:caption>';
    strGrid += '<w2:header id="header1">';
    strGrid += '<w2:row id="hrow1">';
    strGrid += '<w2:column id="col_name_h" value="name" width="180" inputType="text" displayMode="label"></w2:column>';
    strGrid += '<w2:column id="col_desc_h" value="desc" width="180" inputType="text" displayMode="label"></w2:column>';
    strGrid += '</w2:row>';
    strGrid += '</w2:header>';
    strGrid += '<w2:gBody id="gBody1">';
    strGrid += '<w2:row id="brow1">';
    strGrid += '<w2:column id="name" value="" width="180" inputType="text" displayMode="label"></w2:column>';
    strGrid += '<w2:column id="desc" value="" width="180" inputType="text" displayMode="label"></w2:column>';
    strGrid += '</w2:row>';
    strGrid += '</w2:gBody>';
    strGrid += '</w2:gridView>';

    scwin.gridview1 = await $p.dynamicCreate(
        "gridview1",
        "gridView",
        strGrid,
        grp_comp
    );
};



// placeholder / 바인딩값 확인
scwin.btn_getPlaceholder_onclick = function (e) {
    let elem = document.querySelector("#" + target1.getID() + " input");

    if (elem) {
        wf_body_bottom.getObj("scwin").setReturnValue("placeholder : " + elem.getAttribute('placeholder'));
        wf_body_bottom.getObj("scwin").setReturnValue("value : " + elem.value);
    }

    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : " + target1.getValue());
};



// GridView 행 선택 해제 (DataList + GridView 양쪽 모두 해제)
scwin.btn_unselectRow_onclick = function (e) {
    // DataList 측 행 미선택 (ref 값 빈값 → searchbox placeholder 표시)
    dlt_ref.setRowPosition();

    // GridView 측 포커스 상태 모두 해제 (행 강조 표시 제거)
    gridview1.removeFocusedCell();

    wf_body_bottom.getObj("scwin").setReturnValue("dlt_ref.setRowPosition() + gridview1.removeFocusedCell() 실행 (행 선택 해제)");
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : " + target1.getValue());
};
